import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-09-25","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-09-25","date":"2024-09-25T00:00:00.000Z","updated":"2024-09-26T00:00:00.000Z","tags":["Ceph版本发布","多区域复制","加密对象复制","索引存储优化","Ceph RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-25.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-25.md","lastUpdated":1780459816000}'),r={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-25.md"};function o(n,e,h,s,p,c){return i(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-版本发布流程及多区域复制讨论" tabindex="-1">会议主题：Ceph 版本发布流程及多区域复制讨论 <a class="header-anchor" href="#会议主题-ceph-版本发布流程及多区域复制讨论" aria-label="Permalink to &quot;会议主题：Ceph 版本发布流程及多区域复制讨论&quot;">​</a></h4><h4 id="参会人员-ceph-开发团队成员" tabindex="-1">参会人员：Ceph 开发团队成员 <a class="header-anchor" href="#参会人员-ceph-开发团队成员" aria-label="Permalink to &quot;参会人员：Ceph 开发团队成员&quot;">​</a></h4><h4 id="会议时间-2024年9月25日" tabindex="-1">会议时间：2024年9月25日 <a class="header-anchor" href="#会议时间-2024年9月25日" aria-label="Permalink to &quot;会议时间：2024年9月25日&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Ceph 版本发布流程</strong></p><ul><li>讨论了创建候选版本（release candidates）和最终版本（G8）的过程。</li><li>解释了从主分支（squid branch）创建发布分支（squid release branch）的步骤。</li><li>讨论了哪些 bug 修复或 PR（Pull Request）可以进入发布分支。</li><li>确认下一个版本 19.21 将从最新的 squid 分支创建。</li></ul></li><li><p><strong>多区域复制（Multi-site Replication）</strong></p><ul><li>讨论了在多区域集群中数据复制的实现问题，特别是 bucket 的创建和删除操作。</li><li>提出了在多区域环境中处理 bucket 复制的新方法，包括使用系统账户和优化同步管道（sync pipes）。</li><li>讨论了如何通过测试案例来验证多区域复制的正确性。</li></ul></li><li><p><strong>加密对象的复制操作</strong></p><ul><li>讨论了支持加密对象的复制操作的进展，目前有一个分支正在进行中，但需要更新和重新测试。</li></ul></li><li><p><strong>索引存储优化</strong></p><ul><li>提出了使用图形索引（graph-based indexes）替代当前的哈希索引，以提高索引的查询效率和一致性。</li><li>讨论了当前正在进行的相关工作，并计划进一步讨论和合作。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了下一个 Ceph 版本 19.21 的发布流程和时间表。</li><li>同意继续优化和测试多区域复制功能，特别是在处理 bucket 操作和数据同步方面。</li><li>计划更新并重新测试加密对象的复制操作，以尽快支持这一功能。</li><li>计划进一步讨论和探索使用图形索引的可能性，并寻求社区的合作和支持。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续跟踪和更新发布流程文档，确保所有团队成员都能理解和遵循。</li><li>增加多区域复制的测试案例，以验证功能的正确性和性能。</li><li>更新加密对象复制操作的分支，并重新进行测试和验证。</li><li>组织进一步的讨论和合作，以探索和实现图形索引的优化方案。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议主要讨论了 Ceph 的版本发布流程、多区域复制功能的优化以及加密对象的复制操作。团队成员对当前的进展和存在的问题进行了深入的讨论，并制定了相应的后续行动计划。通过不断的优化和测试，Ceph 将继续提升其在分布式存储领域的性能和可靠性。</p>',12)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
